func (q *Queries) QueuePush(ctx context.Context, arg QueuePushParams) error {
	_, err := q.db.Exec(ctx, queuePush,
		arg.EventID,
		arg.CalendarID,
		arg.ExternalUid,
		arg.Payload,
		arg.Deleted,
		arg.Now,
	)
	return err
}

