const setGoogleExportPayload = `-- name: SetGoogleExportPayload :execrows
UPDATE google_exports
SET payload = $1, payload_at = $2::timestamptz, deleted = false,
    next_attempt_at = CASE WHEN state <> 'synced' AND next_attempt_at IS NULL THEN $2::timestamptz ELSE next_attempt_at END,
    updated_at = now()
WHERE event_id = $3
`

type SetGoogleExportPayloadParams struct {
	Payload []byte
	Now     pgtype.Timestamptz
	EventID pgtype.UUID
}

// Records the event as the feed gives it without queuing an export (a
// snapshot of an event already exported, or export off). A waiting export
// that had no payload yet becomes due.
func (q *Queries) SetGoogleExportPayload(ctx context.Context, arg SetGoogleExportPayloadParams) (int64, error) {
	result, err := q.db.Exec(ctx, setGoogleExportPayload, arg.Payload, arg.Now, arg.EventID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

